//! ID-51 Plus MENU settings: the field table, read out of the radio's own
//! `.icf` and written back into one.
//!
//! The byte rules are Icom's — big-endian integers, space- or FF-padded text,
//! off = 0 / on = 1 — so the encoder is the ID-52's, and the extras the table cannot express (the
//! 12-byte manual-position record, the MY call sign layout, the sentence
//! limits) are the ID-5100's, shared through its [`ApplyRules`]. Only the
//! table is this radio's.
//!
//! ## Where the table came from
//!
//! GENERATED by `scratchpad/icom_id51/gen_table.py` from `MEASURED.md`. Every
//! address was measured by driving Icom's CS-51PLUS inside a VM — move one
//! control, save, diff — and every label read off CS-51PLUS's own dropdown. The
//! instrument was validated first: two untouched CS saves are byte-identical,
//! and opening the radio's own file and saving it changes no setting byte.
//! Each pass's final state was read back off CS's screen against the decode,
//! which caught nothing wrong across ~200 fields.

use serde_json::{Map, Value};

use crate::radios::icom_id52::settings::{SF, SK};
use crate::radios::icom_id5100::settings::{apply_with, decode_with, ApplyRules, Limit};

include!("id51_settings_table.rs");

/// The GPS Manual Position record — the ID-5100's 12-byte layout exactly,
/// measured here by typing 40°35.12'N 105°04.56'W into CS-51PLUS (g015-g018):
/// `28 89 30 'N' 69 11 D0 'W'`, then altitude as i32 BE tenths of a foot,
/// `7FFFFFFF` = blank.
const POSITIONS: &[(&str, usize)] = &[("gps-manual-position", 0x1AB6C)];

/// The sentence limits CS-5100 enforces on the ID-5100 (at most 4 NMEA
/// sentences, at least 1 logger sentence), kept here as the conservative rule.
/// ⚠ NOT measured on the ID-51: every CS-51PLUS sentence pass stayed inside
/// them on purpose, so neither the refusal nor its absence has been seen. A
/// profile outside them leaves that group as the radio has it, and the export
/// report says so.
const LIMITS: &[Limit] = &[
    (
        "GPS TX (NMEA) sentences",
        &[
            "gps-tx-nmea-sentence-rmc",
            "gps-tx-nmea-sentence-gga",
            "gps-tx-nmea-sentence-gll",
            "gps-tx-nmea-sentence-gsa",
            "gps-tx-nmea-sentence-vtg",
            "gps-tx-nmea-sentence-gsv",
        ],
        0,
        4,
    ),
    (
        "GPS Logger record sentences",
        &[
            "gps-logger-record-sentence-rmc",
            "gps-logger-record-sentence-gga",
            "gps-logger-record-sentence-vtg",
            "gps-logger-record-sentence-gsa",
        ],
        1,
        4,
    ),
];

pub(crate) const ID51_RULES: ApplyRules = ApplyRules {
    radio: "ID-51",
    fields: ID51_SETTINGS_FIELDS,
    positions: POSITIONS,
    limits: LIMITS,
    // CS-51PLUS's MY call layout for a suffix is unmeasured (m010 typed a plain
    // call): store what the operator typed, uppercased.
    call_sign_layout: false,
};

/// Every setting the table knows, decoded out of the radio's `.icf` image and
/// shaped like the profile form.
pub(crate) fn decode_settings(image: &[u8]) -> Value {
    decode_with(&ID51_RULES, image)
}

/// Write a profile's settings into the image. Returns how many were applied
/// and a note for each one that could not be (an unknown key, a refused sentence
/// combination, an unparseable position). A blank field means "leave alone".
pub(crate) fn apply_settings(image: &mut [u8], settings: &Map<String, Value>) -> (usize, Vec<String>) {
    apply_with(&ID51_RULES, image, &Value::Object(settings.clone()))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Whole bytes a field owns; bit fields own none (they share their byte).
    fn len(f: &SF) -> usize {
        match &f.kind {
            SK::BoolBit { .. } | SK::EnumBits { .. } => 0,
            _ => crate::radios::icom_id52::settings::field_end(f) - f.byte as usize,
        }
    }

    /// No two whole-byte fields claim the same byte, and no two bit fields the
    /// same bit — a misread pass would show up as a collision.
    #[test]
    fn no_two_settings_share_a_byte_or_a_bit() {
        let mut bytes = std::collections::HashMap::new();
        let mut bits = std::collections::HashMap::new();
        for f in ID51_SETTINGS_FIELDS {
            for b in f.byte as usize..f.byte as usize + len(f) {
                if let Some(o) = bytes.insert(b, f.key) {
                    panic!("{} and {o} both claim {b:#x}", f.key);
                }
            }
            let span = match &f.kind {
                SK::BoolBit { shift } => Some((*shift, 1)),
                SK::EnumBits { shift, bits, .. } => Some((*shift, *bits)),
                _ => None,
            };
            if let Some((shift, n)) = span {
                assert!(!bytes.contains_key(&(f.byte as usize)), "{} shares a whole-byte field's byte", f.key);
                for bit in shift..shift + n {
                    if let Some(o) = bits.insert((f.byte, bit), f.key) {
                        panic!("{} and {o} both claim bit {bit} of {:#x}", f.key, f.byte);
                    }
                }
            }
        }
        // Bit fields sharing a byte with a whole-byte field would be overwritten.
        for (byte, _) in bits.keys() {
            assert!(!bytes.contains_key(&(*byte as usize)), "bit field byte {byte:#x} is also a whole-byte field");
        }
    }

    /// The form and the table come out of one generator run; this holds them
    /// together, plus the three position fields the codec adds.
    #[test]
    fn schema_and_table_cover_the_same_keys() {
        let schema: Vec<Value> = serde_json::from_str(crate::seed::ID51_SETTINGS_SCHEMA).unwrap();
        let mut form: Vec<&str> = schema
            .iter()
            .filter(|f| f["type"] != "section")
            .map(|f| f["key"].as_str().unwrap())
            .collect();
        let mut table: Vec<String> = ID51_SETTINGS_FIELDS.iter().map(|f| f.key.to_string()).collect();
        for (k, _) in POSITIONS {
            for s in ["latitude", "longitude", "altitude-m"] {
                table.push(format!("{k}-{s}"));
            }
        }
        form.sort_unstable();
        table.sort_unstable();
        assert_eq!(form, table);
    }

    /// Every field sits in the settings block or the two text tables, inside
    /// the image.
    #[test]
    fn every_field_is_inside_the_image() {
        for f in ID51_SETTINGS_FIELDS {
            assert!(f.byte as usize + len(f).max(1) <= super::super::layout::IMAGE_LEN, "{}", f.key);
        }
    }

    /// A MY call sign is stored as typed (uppercased) — not rearranged by the
    /// ID-5100's measured suffix rule, which nobody has checked on this radio.
    #[test]
    fn my_call_signs_are_stored_as_typed() {
        let mut image = vec![0u8; super::super::layout::IMAGE_LEN];
        let mut m = Map::new();
        m.insert("my-station-my-call-sign-m01".into(), Value::from("ww8l-7"));
        let (n, notes) = apply_settings(&mut image, &m);
        assert_eq!((n, notes.len()), (1, 0));
        assert_eq!(&image[0x1519E..0x151A6], b"WW8L-7  ");
    }

    /// The bit fields that share `0x1AB34` are read-modify-written: setting
    /// ATT(AM) leaves ATT(AIR), ATT(FM) and the unidentified low nibble alone.
    #[test]
    fn att_am_is_written_inside_its_two_bits() {
        let mut image = vec![0u8; super::super::layout::IMAGE_LEN];
        image[0x1AB34] = 0b1100_1111; // AIR on, FM on, AM OFF, nibble F
        let mut m = Map::new();
        m.insert("bc-radio-att-am".into(), Value::from("50dB"));
        let (n, notes) = apply_settings(&mut image, &m);
        assert_eq!((n, notes.len()), (1, 0));
        assert_eq!(image[0x1AB34], 0b1111_1111);
        assert_eq!(decode_settings(&image)["bc-radio-att-am"], "50dB");
        assert_eq!(decode_settings(&image)["others-att-air"], true);
    }
}
